const names = { 'habr.com': 'Хабр', 'github.blog': 'GitHub Changelog', 'blog.cloudflare.com': 'Cloudflare Blog' }
const saved = new Set($('Хранилище').first().json.news.map(item => item.id))
const now = Date.now()
const limit = Math.min(5, Math.max(1, Number($env.DIGEST_PER_SOURCE) || 5))
const candidates = []
for (const { json: item } of $input.all()) {
  if (!item.link || !item.title) continue
  const link = String(item.link).split('#')[0].replace(/\?utm_[^#]*$/, '')
  const host = link.match(/^https:\/\/([^/]+)\//i)?.[1]?.toLowerCase()
  const source = names[host]
  const time = Date.parse(item.isoDate ?? item.pubDate ?? '')
  const title = String(item.title).replace(/\s+/g, ' ').trim()
  const text = String(item.contentSnippet || item.summary || item.content || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim()
  if (!source || !title || !text || link.length > 360 || saved.has(link)
    || !Number.isFinite(time) || time < now - 86400000 || time > now + 300000) continue
  candidates.push({ time, id: link, link, date: new Date(time).toISOString(), source, title: title.slice(0, 220), text: text.slice(0, 1000) })
}
candidates.sort((a, b) => b.time - a.time)
const counts = {}
const selected = []
for (const item of candidates) {
  if (saved.has(item.id) || (counts[item.source] ?? 0) >= limit) continue
  saved.add(item.id)
  counts[item.source] = (counts[item.source] ?? 0) + 1
  selected.push({ json: item })
}
return selected

