const allowed = new Set(['ИИ', 'программирование', 'безопасность', 'железо', 'наука', 'бизнес', 'интернет'])
const source = $('Свежие новости').all()
const items = []
$input.all().forEach((item, index) => {
  let answer
  try { answer = JSON.parse(item.json.message?.content ?? '') } catch { return }
  if (!answer || typeof answer.summary !== 'string' || !Array.isArray(answer.tags)) return
  const summary = answer.summary.replace(/\s+/g, ' ').trim()
  const tags = [...new Set(answer.tags.filter(tag => allowed.has(tag)))].slice(0, 3)
  if (summary.length < 25 || summary.length > 520 || !tags.length) return
  const { id, date, source: publisher, title, link } = source[index].json
  items.push({ json: { id, date, source: publisher, title, summary, tags, link } })
})
if (!items.length) throw new Error('Ollama не вернула ни одной пригодной новости')
return items

const result = $input.first().json
if (result.error || !Number.isInteger(result.accepted ?? result.added)) throw new Error('Хранилище отклонило запись')
return [{ json: { accepted: result.accepted ?? result.added } }]
